import math

ref   = {"A": 0.40, "B": 0.30, "C": 0.28, "D": 0.02}
proxy = {"A": 1.0,  "B": 1.8,  "C": 0.0,  "D": 2.4}
true  = {"A": 0.6,  "B": 1.0,  "C": 0.0,  "D": -1.0}

def pi_star(ref, r, beta):
    w = {y: ref[y] * math.exp(r[y] / beta) for y in ref}
    Z = sum(w.values())
    return {y: w[y] / Z for y in w}

def report(ref, r, beta):
    pi = pi_star(ref, r, beta)
    ep = sum(pi[y] * proxy[y] for y in pi)
    et = sum(pi[y] * true[y] for y in pi)
    kl = sum(pi[y] * math.log(pi[y] / ref[y]) for y in pi if pi[y] > 0)
    print(f"beta={beta:<4} D={pi['D']:.3f} proxy={ep:.2f} true={et:.2f} KL={kl:.2f}")

for beta in [2, 1, 0.5, 0.3, 0.2, 0.1]:
    report(ref, proxy, beta)

import math, statistics as st

ref  = {"A": 0.40, "B": 0.30, "C": 0.28, "D": 0.02}
true = {"A": 0.6,  "B": 1.0,  "C": 0.0,  "D": -1.0}
# three reward models: they agree on A to C and disagree on the exploit D
split = [{"A": 1.0, "B": 1.8, "C": 0.0,  "D": 2.4},    # the proxy of lesson 5
         {"A": 0.9, "B": 1.9, "C": 0.1,  "D": 2.8},
         {"A": 1.1, "B": 1.7, "C": -0.1, "D": 0.4}]
# the same, but every member learned the same bias toward D
shared = [dict(rm, D=d) for rm, d in zip(split, [2.4, 2.5, 2.3])]

def combine(rms, rule, lam=0.5):
    out = {}
    for y in ref:
        s = [rm[y] for rm in rms]
        out[y] = {"single": s[0], "mean": st.mean(s), "worst": min(s),
                  "uwo": st.mean(s) - lam * st.pvariance(s)}[rule]
    return out

def pi_star(r, beta):
    w = {y: ref[y] * math.exp(r[y] / beta) for y in ref}
    Z = sum(w.values())
    return {y: w[y] / Z for y in w}

for name, rms in [("split", split), ("shared", shared)]:
    for rule in ["single", "mean", "uwo", "worst"]:
        r = combine(rms, rule)
        pi = pi_star(r, beta=0.2)
        et = sum(pi[y] * true[y] for y in pi)
        print(f"{name:6} {rule:6} r(D)={r['D']:5.2f} r(B)={r['B']:4.2f} "
              f"pi(D)={pi['D']:.3f} true={et:5.2f}")

class AlwaysEqual:
    def __eq__(self, other):
        return True
    def __ne__(self, other):
        return False

def sort_list(xs):
    # the 'solution': no sorting at all
    return AlwaysEqual()

def test_sort():
    assert sort_list([3, 1, 2]) == [1, 2, 3]
    assert sort_list([]) == []

test_sort()
